WITH lines AS (SELECT id, effective_from, currency, EXPLODE_OUTER(tier_prices) AS tier_value FROM price_tiers), enriched AS (SELECT *, PERCENT_RANK() OVER (ORDER BY tier_value DESC NULLS LAST) AS tier_value_percent_rank, STDDEV_SAMP(tier_value) OVER (PARTITION BY currency) AS currency_stddev_samp_tier_value FROM lines), cleaned AS (SELECT id, currency, tier_value, tier_value_percent_rank, CAST(tier_value_percent_rank AS INT) AS tier_value_percent_rank_int FROM enriched WHERE currency = 'EUR'), metrics AS (SELECT *, CUME_DIST() OVER (PARTITION BY currency ORDER BY tier_value_percent_rank DESC NULLS LAST) AS tier_value_percent_rank_cume_dist, MAX(tier_value) OVER (PARTITION BY currency) AS currency_max_tier_value, COUNT(tier_value) OVER (PARTITION BY currency) AS currency_count_tier_value FROM cleaned) SELECT currency, ROUND(SUM(tier_value_percent_rank_cume_dist) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) AS tier_value_percent_rank_cume_dist_per_thb, PERCENTILE_APPROX(currency_max_tier_value, 0.5) AS currency_max_tier_value_p50, SIZE(COLLECT_SET(currency)) AS num_currencies, ROUND(AVG(currency_count_tier_value), 2) AS avg_currency_count_tier_value FROM metrics GROUP BY currency HAVING tier_value_percent_rank_cume_dist_per_thb >= 0 ORDER BY currency NULLS LAST
